from lib import *
S = SS('p2')
steps = [
    step("默认的 HTTPAdapter 是 pool_connections=10、pool_maxsize=10、pool_block=False。30 个线程共用一个 Session,每个请求在服务器上停 0.2 秒:服务器同时在处理的请求峰值是 30,累计接受 30 条连接,总耗时 220 ms。pool_maxsize 并不限制并发——池满时 requests 照样新建连接,只是用完后放不回池里:urllib3 记了 20 条 WARNING,原文是 Connection pool is full, discarding connection: 127.0.0.1. Connection pool size: 10。", t=tl(S(1)), done=lidx(S(1), '累计接受 30 条连接'), mark=lidx(S(1), '警告 20 条', 'pool_maxsize=10'), b=bars([['服务器并发峰值', 30, '30'], ['累计连接', 30, '30'], ['被丢弃的连接(警告)', 20, '20']], 30, mark=[2], done=[0, 1]), kv=KV([['pool_maxsize', '10(不限制并发)'], ['并发峰值', '30'], ['警告', '20 条,放不回池里的连接']], ['警告'])),
    step("代价在第二波才显现:默认 pool_maxsize=10 时,第 1 波累计 30 条连接,警告 20 条;池里只留下了 10 条,第 2 波再来 30 个并发,只能复用 10 条、新开 20 条,累计 50 条,累计警告 40 条。pool_maxsize=30 时第 1 波 30 条连接、没有警告,第 2 波新增 0 条,累计仍是 30。每一波的耗时都在 213–222 ms,本机回环下看不出建连接的时间差,但连接数是实打实多出来的。", t=tl(S(2)), done=lidx(S(2), 'pool_maxsize=30:'), mark=lidx(S(2), '默认 pool_maxsize=10:'), b=bars([['默认 maxsize=10:累计连接', 50, '50'], ['maxsize=30:累计连接', 30, '30']], 50, mark=[0], done=[1]), kv=KV([['maxsize=10', '第二波新增 20 条,累计 50'], ['maxsize=30', '第二波新增 0 条,累计 30'], ['警告', '40 条 对 0 条']], ['maxsize=10'])),
    step("想真正限制并发,要加 pool_block=True:池里没有空闲连接时线程排队等。pool_maxsize=10 加 pool_block=True,30 个并发请求总耗时 623 ms,服务器同时处理的峰值只有 10,累计只用了 10 条连接,0 条警告;3 批 × 200 ms = 600 ms 是理论下限。对照 pool_maxsize=30 不阻塞:233 ms、峰值 30、30 条连接。限制并发和复用连接是两回事,要用 pool_block 才能换到“并发上限”。", t=tl(S(3)), done=lidx(S(3), 'pool_maxsize=10, pool_block=True'), mark=lidx(S(3), '理论下限', '对照 pool_maxsize=30'), b=bars([['block=True,maxsize=10 (ms)', 623, '623'], ['理论下限 3 批 (ms)', 600, '600'], ['maxsize=30 (ms)', 233, '233']], 700, done=[0], mark=[2]), kv=KV([['pool_block=True', '并发峰值 10,10 条连接,0 警告'], ['pool_maxsize=30', '并发峰值 30,30 条连接'], ['耗时', '623 ms 对 233 ms']], ['pool_block=True'])),
    step("pool_connections 是 PoolManager 缓存的“主机池”个数,不是连接数:3 个不同端口的服务器轮流各请求 4 次(共 12 次)。pool_connections=1 时每个服务器都累计 4 条连接——每次换主机就把上一个主机的池挤掉,哪个主机都复用不了;pool_connections=3 时每个服务器只有 1 条连接。爬很多个域名时,这个值太小等于每次都重新建连接。", t=tl(S(4)), done=lidx(S(4), 'pool_connections=3'), mark=lidx(S(4), 'pool_connections=1'), b=bars([['pool_connections=1 的连接数/主机', 4, '4'], ['pool_connections=3 的连接数/主机', 1, '1']], 4, mark=[0], done=[1]), kv=KV([['pool_connections=1', '3 个主机各 4 条连接'], ['pool_connections=3', '3 个主机各 1 条连接'], ['含义', '缓存多少个主机的池']], ['pool_connections=1'])),
]
A = mkartp('p2', 2, '爬虫,requests,连接池,HTTPAdapter,pool_maxsize,pool_block,Python,真实验证,动画演示',
    '在本机测试服务器上实测 requests 的连接池:默认 pool_maxsize=10 并不限制并发,30 个并发请求会开出 30 条连接并丢弃 20 条(WARNING: Connection pool is full);第二波再开 20 条;pool_block=True 才能把并发限制在 10;pool_connections 是缓存的主机池个数。',
    'requests 的 pool_maxsize 经常被误解成“最大并发”。这篇用 30 个线程共用一个 Session,看服务器同时接了多少条连接、连接池里到底留住了多少,以及 pool_maxsize、pool_block、pool_connections 各管什么。',
    [('30 / 10', '30 并发请求时服务器的并发峰值;默认池容量 10,并不拦着你'), ('50 条', '默认池容量下连续两波 30 并发累计开出的连接(池足够大时只有 30 条)'), ('623 ms', 'pool_block=True 时 30 个请求排队跑完,服务器峰值只有 10')],
    [('pool_maxsize 不是并发上限', '<p>默认的 <code>HTTPAdapter</code> 是 <code>pool_connections=10</code>、<code>pool_maxsize=10</code>、<code>pool_block=False</code>。池里没有空闲连接时,urllib3 照样新建一条;用完后如果池里已经有 10 条,就把多出来的连接关掉并记一条 WARNING:<code>Connection pool is full, discarding connection</code>。所以 30 个线程能同时跑出 30 条连接。</p>'),
     ('被丢弃的连接要重建', '<p>多出来的连接不是免费的。第二波 30 个并发来的时候,池里只剩 10 条,另外 20 条要重新建。把 <code>pool_maxsize</code> 调到不小于线程数,第二波就能全部复用。日志里反复出现“pool is full”警告,就是在提示这件事。</p>'),
     ('用 pool_block 限制并发', '<p>想让池真的限制并发,要设 <code>pool_block=True</code>:池里没有可用连接时线程等待,服务器的并发峰值就被压到 <code>pool_maxsize</code>。实测 30 个请求花了 623 ms,比 3 批 × 200 ms 的理论下限只多 23 ms。代价是线程会被卡住(这里没有配合超时测试等待连接会不会超时)。</p>'),
     ('pool_connections:缓存几个主机', '<p><code>pool_connections</code> 是 PoolManager 缓存的主机池个数。只留 1 个时,在多个主机间交替请求,每次都新建连接;留 3 个就每个主机复用 1 条。抓很多个域名的爬虫要注意这个值——我只测了“交替访问 3 个主机”这一种模式,没有测更多主机时的淘汰顺序。</p>')],
    steps,
    [ENV_P + '。30 个线程用 ThreadPoolExecutor 共用一个 Session;服务器每个请求停 0.2 秒,记录同时在处理的请求峰值(并发)和累计接受的连接数;“Connection pool is full”警告通过给 urllib3.connectionpool 日志器挂 Handler 计数;每种配置各跑一遍',
     '没有验证:真实网络下连接建立的实际耗时(本机回环看不出);pool_block=True 时等待连接的超时行为;pool_connections 的具体淘汰顺序(只测了交替访问);aiohttp 等其它库的连接池参数(后面的文章会单独看);HTTPS 连接池(池规则相同,但没有单独验证)'],
    '连接池大小')
